CREATE TYPE "ProfessionalIntelligenceStatus" AS ENUM ('ACTIVE','ARCHIVED'); CREATE TYPE "ProfessionalSourceType" AS ENUM ('DECLARED','OBSERVED','DERIVED','INFERRED','VERIFIED'); CREATE TYPE "ProfessionalRecordStatus" AS ENUM ('ACTIVE','INACTIVE'); CREATE TYPE "VerificationStatus" AS ENUM ('UNVERIFIED','PENDING','VERIFIED','REJECTED','EXPIRED');
CREATE TABLE "ProfessionalIntelligenceProfile" ("id" TEXT NOT NULL,"businessId" TEXT NOT NULL,"professionalId" TEXT NOT NULL,"version" INTEGER NOT NULL DEFAULT 1,"status" "ProfessionalIntelligenceStatus" NOT NULL DEFAULT 'ACTIVE',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ProfessionalIntelligenceProfile_pkey" PRIMARY KEY("id"),CONSTRAINT "ProfessionalIntelligenceProfile_businessId_fkey" FOREIGN KEY("businessId") REFERENCES "Business"("id") ON DELETE CASCADE,CONSTRAINT "ProfessionalIntelligenceProfile_businessId_professionalId_fkey" FOREIGN KEY("businessId","professionalId") REFERENCES "Staff"("businessId","id") ON DELETE CASCADE); CREATE UNIQUE INDEX "ProfessionalIntelligenceProfile_businessId_professionalId_key" ON "ProfessionalIntelligenceProfile"("businessId","professionalId"); CREATE UNIQUE INDEX "ProfessionalIntelligenceProfile_businessId_id_key" ON "ProfessionalIntelligenceProfile"("businessId","id"); CREATE INDEX "ProfessionalIntelligenceProfile_businessId_status_updatedAt_idx" ON "ProfessionalIntelligenceProfile"("businessId","status","updatedAt");
