CREATE TABLE "ProfessionalSkillEvidence" ("id" TEXT NOT NULL,"businessId" TEXT NOT NULL,"skillId" TEXT NOT NULL,"sourceType" TEXT NOT NULL,"sourceId" TEXT NOT NULL,"idempotencyKey" TEXT NOT NULL,"weight" DECIMAL(5,4) NOT NULL,"occurredAt" TIMESTAMP(3) NOT NULL,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ProfessionalSkillEvidence_pkey" PRIMARY KEY("id"),CONSTRAINT "ProfessionalSkillEvidence_businessId_skillId_fkey" FOREIGN KEY("businessId","skillId") REFERENCES "ProfessionalSkill"("businessId","id") ON DELETE CASCADE); CREATE UNIQUE INDEX "ProfessionalSkillEvidence_businessId_idempotencyKey_key" ON "ProfessionalSkillEvidence"("businessId","idempotencyKey"); CREATE INDEX "ProfessionalSkillEvidence_businessId_skillId_occurredAt_idx" ON "ProfessionalSkillEvidence"("businessId","skillId","occurredAt"); CREATE INDEX "ProfessionalSkillEvidence_businessId_sourceType_sourceId_idx" ON "ProfessionalSkillEvidence"("businessId","sourceType","sourceId");
CREATE TABLE "ProfessionalExperience" ("id" TEXT NOT NULL,"businessId" TEXT NOT NULL,"profileId" TEXT NOT NULL,"organizationName" TEXT NOT NULL,"role" TEXT NOT NULL,"specialization" TEXT,"startDate" TIMESTAMP(3) NOT NULL,"endDate" TIMESTAMP(3),"sourceType" "ProfessionalSourceType" NOT NULL DEFAULT 'DECLARED',"verificationStatus" "VerificationStatus" NOT NULL DEFAULT 'UNVERIFIED',"status" "ProfessionalRecordStatus" NOT NULL DEFAULT 'ACTIVE',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ProfessionalExperience_pkey" PRIMARY KEY("id"),CONSTRAINT "ProfessionalExperience_businessId_profileId_fkey" FOREIGN KEY("businessId","profileId") REFERENCES "ProfessionalIntelligenceProfile"("businessId","id") ON DELETE CASCADE); CREATE INDEX "ProfessionalExperience_businessId_profileId_status_startDate_idx" ON "ProfessionalExperience"("businessId","profileId","status","startDate");
CREATE TABLE "ProfessionalCredential" ("id" TEXT NOT NULL,"businessId" TEXT NOT NULL,"profileId" TEXT NOT NULL,"kind" TEXT NOT NULL,"issuer" TEXT NOT NULL,"title" TEXT NOT NULL,"issuedAt" TIMESTAMP(3) NOT NULL,"expiresAt" TIMESTAMP(3),"credentialReference" TEXT,"sourceType" "ProfessionalSourceType" NOT NULL DEFAULT 'DECLARED',"verificationStatus" "VerificationStatus" NOT NULL DEFAULT 'UNVERIFIED',"status" "ProfessionalRecordStatus" NOT NULL DEFAULT 'ACTIVE',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ProfessionalCredential_pkey" PRIMARY KEY("id"),CONSTRAINT "ProfessionalCredential_businessId_profileId_fkey" FOREIGN KEY("businessId","profileId") REFERENCES "ProfessionalIntelligenceProfile"("businessId","id") ON DELETE CASCADE); CREATE INDEX "ProfessionalCredential_businessId_profileId_status_issuedAt_idx" ON "ProfessionalCredential"("businessId","profileId","status","issuedAt");
